10	import net.officefloor.hq.app.period.Period;
11	import net.officefloor.hq.app.period.PeriodRepository;
12	import net.officefloor.hq.app.person.PersonRepository;
13	import net.officefloor.hq.app.rate.Rate;
14	import net.officefloor.hq.app.rate.RateService;
15	import net.officefloor.hq.app.rollup.Rollup;
16	import net.officefloor.hq.app.setting.Role;
17	import net.officefloor.hq.app.setting.SettingService;
18	import net.officefloor.hq.app.sheet.SheetRepository;
19	import net.officefloor.hq.app.sheet.SheetService;
20	import org.springframework.http.HttpStatus;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	import org.springframework.web.server.ResponseStatusException;
24	
25	@Service
26	public class ClaimService {
27	
28	    private final ClaimRepository claims;
29	    private final PersonRepository people;
30	    private final RateService rates;
31	    private final SheetService sheets;
32	    private final SheetRepository sheetRows;
33	    private final PeriodRepository periods;
34	    private final SettingService settings;
35	    private final Rollup rollup;
36	    private final Audit audit;
37	
38	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
39	            SheetRepository sheetRows, PeriodRepository periods, SettingService settings, Rollup rollup,
40	            Audit audit) {
41	        this.claims = claims;
42	        this.people = people;
43	        this.rates = rates;
44	        this.sheets = sheets;
45	        this.sheetRows = sheetRows;
46	        this.periods = periods;
47	        this.settings = settings;
48	        this.rollup = rollup;
49	        this.audit = audit;
50	    }
51	
52	    /** The sheet's claims, newest first by their place in the list. */
53	    @Transactional(readOnly = true)
54	    public List<Claim> list(String sheetId) {
55	        return claims.findBySheetIdOrderByListedDesc(sheetId);
56	    }
57	
58	    /** Add a claim to a person; a claim with no date is dated the sheet's today. */
59	    @Transactional
60	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
61	            String corrects) {
62	        Person person = person(sheetId, personId);
63	        LocalDate dated = dateOr(sheetId, date);
64	        refuseIfClosed(sheetId, dated);
65	        refuseIfRetired(person, dated);
66	        refuseIfNotCorrecting(sheetId, personId, amount, corrects);
67	        Rollup.Snapshot before = rollup.snapshot(sheetId);
68	        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date.
69	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects,
70	                settings.terms(sheetId, person.gradeOn(dated), dated));
71	        // The sheet is locked (refuseIfClosed), so no other claim takes the same place.
72	        claim.setListed(claims.lastListed(sheetId) + 1);
73	        claim = claims.saveAndFlush(claim);
74	        logStatus(sheetId, user, person, claim);
75	        recordChange("CLAIM_ADDED", user, person, claim);
76	        rollup.recordChanges(user, before);
77	        return claim;
78	    }
79	
80	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
81	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. */
82	    @Transactional
83	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
84	            String corrects) {
85	        Claim claim = claims.findForUpdate(id, sheetId)
86	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
87	        LocalDate dated = dateOr(sheetId, date);
88	        refuseIfClosed(sheetId, claim.getDate());
89	        refuseIfClosed(sheetId, dated);
90	        if (claim.getStatus() != ClaimStatus.DRAFT) {
91	            throw new ResponseStatusException(HttpStatus.CONFLICT,
92	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
93	        }
94	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
95	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
96	        Rollup.Snapshot before = rollup.snapshot(sheetId);
97	        claim.set(amount, dated, noteOf(note), corrects);
98	        Claim saved = claims.saveAndFlush(claim);
99	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
100	        rollup.recordChanges(user, before);
101	        return saved;
102	    }
103	
104	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
105	     *  by the user who opened the claim, and an action the sheet's permission matrix does not allow the
106	     *  user's role. A clerk's settling of a claim whose due is above the sheet's
107	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
108	     *  steward settles anything). */
109	    @Transactional
110	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
111	        Claim claim = claims.findForUpdate(id, sheetId)
112	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
113	        refuseIfClosed(sheetId, claim.getDate());
114	        if (!claim.getStatus().canBecome(next)) {
115	            throw new ResponseStatusException(HttpStatus.CONFLICT,
116	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
117	        }
118	        settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
119	                "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
120	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
121	            throw new ResponseStatusException(HttpStatus.CONFLICT,
122	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
123	        }
124	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
125	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
126	                    "The user who opened a claim cannot settle it.");
127	        }
128	        Person person = person(sheetId, claim.getPersonId());
129	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
130	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
131	        if (next == ClaimStatus.SETTLED) refuseIfUnproven(sheetId, claim, dueNow);
132	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
133	        Rollup.Snapshot before = rollup.snapshot(sheetId);
134	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
135	        claim.setStatus(next);
136	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
137	        // A voided claim keeps its number, which is never given to another claim.
138	        claim.setNumber(number);
139	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
140	        logStatus(sheetId, user, person, claim);
141	        Claim saved = claims.saveAndFlush(claim);
142	        String event = EVENTS.get(next);
143	        if (next == ClaimStatus.SETTLED) {
144	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
145	        } else {
146	            recordChange(event, user, person, saved, number, "");
147	        }
148	        rollup.recordChanges(user, before);
149	        return saved;
150	    }
151	
152	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
153	     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
154	     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
155	    @Transactional
156	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
157	        Claim claim = claims.findForUpdate(id, sheetId)
158	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
159	        refuseIfClosed(sheetId, claim.getDate());
160	        if (claim.getStatus() != ClaimStatus.OPEN) {
161	            throw new ResponseStatusException(HttpStatus.CONFLICT,
162	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
163	        }
164	        if (!until.isAfter(sheets.today(sheetId))) {
165	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
166	                    "A claim can only be deferred to a date after the sheet's today.");
167	        }
168	        Person person = person(sheetId, claim.getPersonId());
169	        Rollup.Snapshot before = rollup.snapshot(sheetId);
170	        claim.deferUntil(until);
171	        Claim saved = claims.saveAndFlush(claim);
172	        recordChange("CLAIM_DEFERRED", user, person, saved, saved.getNumber(), " until=" + until);
173	        rollup.recordChanges(user, before);
174	        return saved;
175	    }
176	
177	    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim, and a claim dated
178	     *  inside a closed period. No figure moves. */
179	    @Transactional
180	    public Claim addProof(String sheetId, String user, long id) {
181	        Claim claim = claims.findForUpdate(id, sheetId)
182	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
183	        refuseIfClosed(sheetId, claim.getDate());
184	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
185	            throw new ResponseStatusException(HttpStatus.CONFLICT,
186	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
187	        }
188	        Person person = person(sheetId, claim.getPersonId());
189	        claim.addProof();
190	        Claim saved = claims.saveAndFlush(claim);
191	        recordChange("CLAIM_PROOF_ADDED", user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
192	        return saved;
193	    }
194	
195	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
196	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
197	     *  its new person's next statement). Refused unless the sheet's permission matrix allows the user's
198	     *  role to reassign (by default, a steward), and for a
199	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
200	     *  or to a person retired by the claim's date. */
201	    @Transactional
202	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
203	        Claim claim = claims.findForUpdate(id, sheetId)
204	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
205	        refuseIfClosed(sheetId, claim.getDate());
206	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
207	                "Your role may not move a claim to another person on this sheet.");
208	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
209	            throw new ResponseStatusException(HttpStatus.CONFLICT,
210	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
211	        }
212	        Person from = person(sheetId, claim.getPersonId());
213	        Person to = person(sheetId, toPersonId);
214	        if (from.getId().equals(to.getId())) {
215	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
216	        }
217	        refuseIfRetired(to, claim.getDate());
218	        Rollup.Snapshot before = rollup.snapshot(sheetId);
219	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
220	        Claim saved = claims.saveAndFlush(claim);
221	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
222	                " from=" + from.getName() + " to=" + to.getName());
223	        rollup.recordChanges(user, before);
224	        return saved;
225	    }
226	
227	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
228	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
229	    @Transactional
230	    public Claim approve(String sheetId, String user, long id) {
231	        Claim claim = pending(sheetId, user, id);
232	        if (user.equals(claim.getOpenedBy())) {
233	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
234	                    "The user who opened a claim cannot approve it.");
235	        }
236	        Person person = person(sheetId, claim.getPersonId());
237	        BigDecimal dueNow = due(sheetId, person, claim);
238	        refuseIfUnproven(sheetId, claim, dueNow);
239	        Rollup.Snapshot before = rollup.snapshot(sheetId);
240	        claim.setStatus(ClaimStatus.SETTLED);
241	        claim.setSettledDue(dueNow);
242	        logStatus(sheetId, user, person, claim);
243	        Claim saved = claims.saveAndFlush(claim);
244	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
245	        rollup.recordChanges(user, before);
246	        return saved;
247	    }
248	
249	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
250	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
251	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
252	    @Transactional
253	    public Claim resettle(String sheetId, String user, long id) {
254	        Claim claim = claims.findForUpdate(id, sheetId)
255	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
256	        refuseIfClosed(sheetId, claim.getDate());
257	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
258	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
259	        }
260	        if (claim.getStatus() != ClaimStatus.SETTLED) {
261	            throw new ResponseStatusException(HttpStatus.CONFLICT,
262	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
263	        }
264	        Person person = person(sheetId, claim.getPersonId());
265	        BigDecimal old = claim.getSettledDue();
266	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim), sheets.today(sheetId),
267	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
268	        Rollup.Snapshot before = rollup.snapshot(sheetId);
269	        claim.setSettledDue(dueNow);
270	        logStatus(sheetId, user, person, claim);
271	        Claim saved = claims.saveAndFlush(claim);
272	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
273	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
274	        rollup.recordChanges(user, before);
275	        return saved;
276	    }
277	
278	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
279	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
280	    @Transactional
281	    public Claim reject(String sheetId, String user, long id, String reason) {
282	        Claim claim = pending(sheetId, user, id);
283	        Person person = person(sheetId, claim.getPersonId());
284	        Rollup.Snapshot before = rollup.snapshot(sheetId);
285	        claim.setStatus(ClaimStatus.OPEN);
286	        logStatus(sheetId, user, person, claim);
287	        Claim saved = claims.saveAndFlush(claim);
288	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
289	        rollup.recordChanges(user, before);
290	        return saved;
291	    }
292	
293	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
294	     *  dated inside a closed period, or the user is not a steward of the sheet. */
295	    private Claim pending(String sheetId, String user, long id) {
296	        Claim claim = claims.findForUpdate(id, sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
298	        refuseIfClosed(sheetId, claim.getDate());
299	        if (claim.getStatus() != ClaimStatus.PENDING) {
300	            throw new ResponseStatusException(HttpStatus.CONFLICT,
301	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
302	        }
303	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
304	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
305	        }
306	        return claim;
307	    }
308	
309	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
310	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
311	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
312	            ClaimStatus.VOID, "void");
313	
314	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
315	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
316	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
317	
318	    private static String text(BigDecimal due) {
319	        return due == null ? "n/a" : due.toPlainString();
320	    }
321	
322	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
323	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
324	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
325	    private String nextNumber(String sheetId, Claim claim) {
326	        LocalDate from = settings.periodNumberingFrom(sheetId);
327	        if (from == null || sheets.today(sheetId).isBefore(from)) {
328	            return Integer.toString(sheets.nextClaimNumber(sheetId));
329	        }
330	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
331	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
332	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
333	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
334	    }
335	
336	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
337	     *  in force on the claim's date (a due of n/a, or no threshold, needs none). */
338	    private void refuseIfUnproven(String sheetId, Claim claim, BigDecimal due) {
339	        if (due == null || claim.getProofs() > 0) return;
340	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
341	        if (threshold != null && due.compareTo(threshold) > 0) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT,
343	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
344	                            + "; add a proof before it is settled.");
345	        }
346	    }
347	
348	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
349	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
350	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
351	        BigDecimal limit = settings.clerkLimit(sheetId);
352	        return limit != null && due.compareTo(limit) > 0;
353	    }
354	
355	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
356	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
357	    private void refuseIfClosed(String sheetId, LocalDate date) {
358	        sheetRows.findForUpdate(sheetId);
359	        if (periods.isClosedOn(sheetId, date)) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
361	        }
362	    }
363	
364	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
365	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
366	        if (amount.signum() >= 0) return;
367	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
368	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
369	        if (!settled) {
370	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
371	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
372	        }
373	    }
374	
375	    /** Refuse a claim dated after its person's retirement date. */
376	    private static void refuseIfRetired(Person person, LocalDate date) {
377	        if (person.isRetiredOn(date)) {
378	            throw new ResponseStatusException(HttpStatus.CONFLICT,
379	                    "The claim is dated after " + person.getName() + " retired.");
380	        }
381	    }
382	
383	    private Person person(String sheetId, long personId) {
384	        return people.findByIdAndSheetId(personId, sheetId)
385	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
386	    }
387	
388	    /** What is due on the claim now: its figure with the late charge on top while it is open and
389	     *  overdue (the charge is never bound by a statement); null when the figure is n/a. */
390	    public BigDecimal due(String sheetId, Person person, Claim claim) {
391	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), sheets.today(sheetId),
392	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
393	    }
394	
395	    /** The figure under the claim's due, before any late charge: the due fixed when it was settled, else the figure
396	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
397	     *  null when that is n/a. */
398	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
399	        if (claim.getSettledDue() != null) return claim.getSettledDue();
400	        if (claim.isBound()) return claim.getStatedDue();
401	        return dueNow(sheetId, person, claim);
402	    }
403	
404	    /** What is due on the claim now at the rate in force on the claim's date of its person's grade in
405	     *  force on that date, rounded
406	     *  as the claim's {@link Rounding} decides and at least the sheet's floor (a correction has no floor); null when no rate of the
407	     *  grade applies by then. */
408	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
409	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
410	        if (rate == null) return null;
411	        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
412	                rounding(sheetId, claim));
413	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
414	    }
415	
416	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
417	     *  correction corrects, else by its own. */
418	    private RoundingMode rounding(String sheetId, Claim claim) {
419	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
420	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
421	                : null;
422	        return Rounding.of(Rounding.dateOf(claim, corrected),
423	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
424	    }
425	
426	    /** Log the status the claim has just taken, with its due as worked out now. */
427	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
428	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
429	    }
430	
431	    private void recordChange(String event, String user, Person person, Claim claim) {
432	        recordChange(event, user, person, claim, claim.getNumber(), "");
433	    }
434	
435	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
436	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
437	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
438	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
439	                + (number == null ? "" : " number=" + number) + extra);
440	    }
441	
442	    private LocalDate dateOr(String sheetId, LocalDate date) {
443	        return date != null ? date : sheets.today(sheetId);
444	    }
445	
446	    private static String noteOf(String note) {
447	        return note == null ? "" : note.trim();
448	    }
449	}
